record(name) {
  ChromeUtils.addProfilerMarker("startupRecorder:" + name);
  this.data.code[name] = {
    modules: Cu.loadedESModules,
    services: Object.keys(Cc).filter(c => {
      try {
        return Cm.isServiceInstantiatedByContractID(c, Ci.nsISupports);
      } catch (e) {
        return false;
      }
    }),
  };

  !AppConstants.MOZ_DEV_EDITION &&
  !AppConstants.DEBUG
) {
  ok(
    !("@mozilla.org/test/startuprecorder;1" in Cc),
    "the startup recorder component shouldn't exist in this non-nightly/non-devedition/" +
      "non-debug build."
  );
  return;
}

const startupRecorder =
  Cc["@mozilla.org/test/startuprecorder;1"].getService().wrappedJSObject;
await startupRecorder.done;

const data = Cu.cloneInto(startupRecorder.data.code, {});
